        // Using inclusion-exclusion:
        // sum_{j=0}^{floor(t/(U+1))} (-1)^j * C(m, j) * C(t - j*(U+1) + m - 1, m - 1)

        long countWithUpperBound(int t, int m, int U) {
            // m variables, each in [0, U], sum = t
            if (t < 0) return 0;
            if (m == 0) return t == 0 ? 1 : 0;
            long res = 0;
            int maxJ = t / (U + 1);
            for (int j = 0; j <= maxJ; j++) {
                long term = nCr(m, j) * nCr(t - j * (U + 1) + m - 1, m - 1) % MOD;
                if (j % 2 == 0) {
                    res = (res + term) % MOD;
                } else {
                    res = (res - term + MOD) % MOD;
                }
            }
            return res;
        }

        // Total number of states
        long totalStates;
        if (p == 1) {
            // Only player 1, a1 = s, must have s >= r
            totalStates = (s >= r) ? 1 : 0;
        } else {
            totalStates = nCr(s - r + p - 1, p - 1);
        }

        if (totalStates == 0) {
            System.out.println(0);
            return;
        }

        long numerator = 0;

        for (int x = r; x <= s; x++) {
            int rem = s - x;
            int m = p - 1; // number of other players

            if (m == 0) {
                // p == 1, player 1 is the only one, always wins
                numerator = (numerator + 1) % MOD;
                continue;
            }

            // A: all ai < x, i.e., ai <= x-1
            long A = countWithUpperBound(rem, m, x - 1);

            // B_k: exactly k of the m variables equal x, rest <= x-1, sum of rest = rem - k*x
            long contrib = A;
            for (int k = 1; k <= m; k++) {
                int rem2 = rem - k * x;
                if (rem2 < 0) break;
                // Choose which k variables are x: C(m, k)
                // The remaining m-k variables sum to rem2, each <= x-1
                long Bk = nCr(m, k) * countWithUpperBound(rem2, m - k, x - 1) % MOD;
                // Contribution: Bk * (1/(k+1))
                long invK1 = modInverse(k + 1, MOD);
                contrib = (contrib + Bk * invK1) % MOD;
            }

            numerator = (numerator + contrib) % MOD;
        }

        // Probability = numerator / totalStates
        long ans = numerator * modInverse(totalStates, MOD) % MOD;
        System.out.println(ans);
    }
}
