                long restWays = F(remAfterK, n - k, x - 1);
                // Probability factor: 1/(k+1)
                long invKPlus1 = modInverse(k + 1, MOD);
                long contrib = chooseK * restWays % MOD * invKPlus1 % MOD;
                winForX = (winForX + contrib) % MOD;
            }

            winStates = (winStates + winForX) % MOD;
        }

        // The probability is winStates / totalStates mod MOD
        long ans = winStates * modInverse(totalStates, MOD) % MOD;
        System.out.println(ans);
