        // Hasan's winning probability in such a state = 1/(j+1)

        for (int k = r; k <= s; k++) {
            int t = s - k;
            for (int j = 0; j <= p - 1; j++) {
                // j other players have score k
                int remainingPlayers = p - 1 - j;
                int remainingSum = t - j * k;
                if (remainingSum < 0) continue;
                long ways = nCr(p - 1, j) * countWithBound(remainingSum, remainingPlayers, k) % MOD;
                // Probability of winning given this configuration = 1/(j+1)
                long prob = modInverse(j + 1, MOD);
                weightedSum = (weightedSum + ways * prob) % MOD;
            }
        }

