        //
        // Let's fix a1 = m. Then m >= r. The other p-1 players have scores summing to s - m.
        // Among these p-1 players, let j be the number of players with score exactly m.
        // The remaining p-1-j players have scores < m, and their sum is (s - m) - j*m.
        //
        // For a fixed m and j:
        //   - We need (s - m) - j*m >= 0, i.e., s - m >= j*m, i.e., s >= m(j+1).
        //   - The number of ways to choose which j of the p-1 players have score m: C(p-1, j)
        //   - The number of ways to assign scores to the remaining p-1-j players such that each is in [0, m-1] and they sum to s - m - j*m:
        //     Let T = s - m - j*m. We need to count the number of non-negative integer solutions to
        //     z1 + z2 + ... + z_{p-1-j} = T with each zi <= m-1.
        //     This is a bounded composition count.
        //
        //   - For each such configuration, Hasan's win probability is 1/(j+1).
        //
        // So W = sum_{m=r}^{s} sum_{j=0}^{p-1} [if s >= m(j+1) and T = s - m(j+1) >= 0]
        //        C(p-1, j) * (number of ways to distribute T among p-1-j players each <= m-1) * (1/(j+1))
        //
        // The number of ways to distribute T among n = p-1-j players each in [0, m-1] is:
        //   sum_{i=0}^{floor(T/m)} (-1)^i * C(n, i) * C(T - i*m + n - 1, n - 1)
        //   (by inclusion-exclusion)
        //   But this is valid only if T >= 0. Also if n = 0, then the count is 1 if T=0 else 0.
        //
        // This approach might be computationally heavy but p <= 100, s <= 5000, so it should be feasible.
        //
        // Let's implement this.

        if (s < r) {
            System.out.println(0);
            return;
        }

        // Precompute factorials and inverse factorials for combinations
        int maxN = s + p; // we might need up to s + p
        long[] fact = new long[maxN + 1];
        long[] invFact = new long[maxN + 1];
        fact[0] = 1;
        for (int i = 1; i <= maxN; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[maxN] = modInverse(fact[maxN], MOD);
        for (int i = maxN - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }

        long comb(int n, int k) {
            if (k < 0 || k > n) return 0;
            return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
        }

        // Total number of valid states
        // a1 >= r, sum = s. Let b1 = a1 - r >= 0. b1 + a2 + ... + ap = s - r.
        // Number of non-negative solutions = C(s - r + p - 1, p - 1)
        long totalStates = comb(s - r + p - 1, p - 1);

        // Now compute W = sum over all valid states of Hasan's win probability
        long W = 0;

        for (int m = r; m <= s; m++) {
            // a1 = m
            // For j = 0 to p-1: number of other players with score m
            for (int j = 0; j <= p - 1; j++) {
                // Total sum for other players: s - m
                // j of them have score m, so remaining sum for p-1-j players: T = s - m - j*m
                int T = s - m - j * m;
                if (T < 0) break; // as j increases, T decreases

                int n = p - 1 - j; // number of remaining players
                if (n < 0) continue;

                // Count number of ways to assign scores to n players, each in [0, m-1], summing to T
                long ways;
                if (n == 0) {
                    ways = (T == 0) ? 1 : 0;
                } else {
                    // Inclusion-exclusion:
                    // Number of non-negative solutions to z1+...+zn = T with zi <= m-1
                    // = sum_{i=0}^{floor(T/m)} (-1)^i * C(n, i) * C(T - i*m + n - 1, n - 1)
                    ways = 0;
                    int maxI = T / m;
                    for (int i = 0; i <= maxI && i <= n; i++) {
                        long term = comb(n, i) * comb(T - i * m + n - 1, n - 1) % MOD;
                        if (i % 2 == 0) {
                            ways = (ways + term) % MOD;
                        } else {
                            ways = (ways - term + MOD) % MOD;
                        }
                    }
                }

                if (ways == 0) continue;

                // Number of ways to choose which j of the p-1 players have score m: C(p-1, j)
                long chooseJ = comb(p - 1, j);

                // Hasan's win probability for each such state: 1/(j+1)
                long winProb = modInverse(j + 1, MOD);

                // Contribution: chooseJ * ways * winProb
                long contrib = chooseJ * ways % MOD * winProb % MOD;
                W = (W + contrib) % MOD;
            }
        }

        W = (W % MOD + MOD) % MOD;

        // Probability = W / totalStates
        long ans = W * modInverse(totalStates, MOD) % MOD;
        System.out.println(ans);
    }
}
